@startuml

class Resident {
  + name : string
  + street_address : string
  + phone_number : string
  + email : string
}

class Item {
  + description : string
  + dimensions : string
  + weight : float
  + category : string
}

class PickupRequest {
  + street_address : string
  + requested_day : date
  + pickup_time_window : string
}

class Vehicle {
  + storage_space : float
}

class Route {
  + date : date
}

class VolunteerDriver {
  + available_days : string[]
}

class H2SLocation {
  + city : string
}

class DistributionCenter {
  + address : string
}

class FoodBank {
  + name : string
}

class H2SEmployee {
  + name : string
}

class Client {
  + home_address : string
  + needed_categories : string[]
}

class Article {
  + rfid_tag : string
  + description : string
}

class PickupVehicle {
}

class DeliveryRoute {
}

Vehicle <|-- PickupVehicle

Resident "1" -- "*" PickupRequest : schedules
PickupRequest "1" -- "*" Item : contains
PickupRequest "*" -- "1" Resident : requested by

H2SLocation "1" -- "0..1" DistributionCenter
H2SLocation "1" -- "1" FoodBank
H2SLocation "1" -- "*" PickupVehicle

VolunteerDriver "1" -- "*" Route : drives
Route "1" -- "1" PickupVehicle : assigned to
Route "1" -- "*" PickupRequest : includes

PickupVehicle "1" -- "*" Article : collects
Article "*" -- "1" DistributionCenter : delivered to
Article "*" -- "1" FoodBank : delivered to

H2SEmployee "1" -- "*" Article : examines
Article "1" -- "1" ArticleCategory : belongs to

Client "0..1" -- "1" DistributionCenter : served by
Client "1" -- "*" Article : receives
VolunteerDriver "1" -- "*" Article : delivers

enum ArticleCategory {
  BABY_CLOTHING
  WOMENS_WINTER_BOOTS
  FRIDGE
  MICROWAVE
}

@enduml

